const respuestas = $input.all();
const candidatosMemoria = $("Leer candidatos pendientes").all();


// ============================================================
// FUNCIONES GENERALES
// ============================================================

function limpiar(texto) {
  return String(texto || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizar(texto) {
  return limpiar(texto)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function dominioDe(url) {
  let texto = String(url || "")
    .trim()
    .toLowerCase();

  texto = texto
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "");

  return texto
    .split("/")[0]
    .split("?")[0]
    .split("#")[0]
    .split(":")[0];
}

function contiene(texto, valor) {
  return normalizar(texto)
    .includes(normalizar(valor));
}


// ============================================================
// COINCIDENCIA CONTROLADA DE PERSONA
//
// Samantha Alban Arboleda
// también puede aparecer públicamente como:
// Samantha Alban
//
// Exigimos al menos los dos primeros componentes del nombre.
// ============================================================

function mencionaPersona(texto, personaCompleta) {

  const t =
    normalizar(texto);

  const persona =
    normalizar(personaCompleta);

  if (!persona) {
    return false;
  }

  // Coincidencia exacta completa
  if (t.includes(persona)) {
    return true;
  }

  const partes =
    persona
      .split(/\s+/)
      .filter(Boolean);

  // No usamos coincidencias de una sola palabra.
  if (partes.length >= 2) {

    const nombreCorto =
      `${partes[0]} ${partes[1]}`;

    if (
      nombreCorto.length >= 6 &&
      t.includes(nombreCorto)
    ) {
      return true;
    }
  }

  return false;
}


// ============================================================
// FUENTES
// ============================================================

function esLinkedInPersonal(url) {

  const u =
    normalizar(url);

  return u.includes("linkedin.com/in/");
}

function esWebCorporativa(url) {

  return dominioDe(url) ===
    "corporacionfavorita.com";
}

function esFuenteFuerte(url) {

  return (
    esLinkedInPersonal(url) ||
    esWebCorporativa(url)
  );
}

function esFuenteMedia(url) {

  const dominio =
    dominioDe(url);

  return (
    dominio === "theorg.com" ||
    dominio === "rocketreach.co" ||
    dominio === "zoominfo.com" ||
    dominio === "x.com"
  );
}


// ============================================================
// EXTRAER CARGO
// ============================================================

function extraerCargo(texto) {

  const t =
    limpiar(texto);

  const patrones = [

    /Gerente\s+de\s+Recursos\s+Humanos/i,
    /Gerente\s+de\s+RRHH/i,
    /Gerente\s+de\s+Talento\s+Humano/i,

    /Jefe\s+Corporativo\s+de\s+Talento\s+Humano/i,
    /Jefa\s+Corporativa\s+de\s+Talento\s+Humano/i,

    /Jefe\s+de\s+Recursos\s+Humanos/i,
    /Jefa\s+de\s+Recursos\s+Humanos/i,

    /Jefe\s+de\s+Talento\s+Humano/i,
    /Jefa\s+de\s+Talento\s+Humano/i,

    /Jefe\s+de\s+TTHH/i,
    /Jefa\s+de\s+TTHH/i,

    /Sub\s+Jefe\s+de\s+Talento\s+Humano(?:,\s*Zona\s+[A-Za-zÁÉÍÓÚáéíóúñÑ]+)?/i,
    /Sub\s+Jefa\s+de\s+Talento\s+Humano(?:,\s*Zona\s+[A-Za-zÁÉÍÓÚáéíóúñÑ]+)?/i,

    /Asistente\s+de\s+Talento\s+Humano/i,
    /Asistente\s+De\s+Talento\s+Humano/i,

    /Coordinador\s+de\s+Talento\s+Humano/i,
    /Coordinadora\s+de\s+Talento\s+Humano/i,

    /Analista\s+de\s+Talento\s+Humano/i,
    /Analista\s+de\s+Recursos\s+Humanos/i,

    /Talento\s+Humano/i,
    /Recursos\s+Humanos/i
  ];

  for (const regex of patrones) {

    const match =
      t.match(regex);

    if (match) {
      return limpiar(match[0]);
    }
  }

  return "NO IDENTIFICADO";
}


// ============================================================
// NORMALIZACIÓN SEMÁNTICA DEL CARGO
//
// Evita considerar conflicto:
//
// Gerente de RRHH
// Gerente de Recursos Humanos
// Gerente de Talento Humano
//
// porque representan la misma familia de cargo.
// ============================================================

function claveCargo(cargo) {

  const c =
    normalizar(cargo);

  if (
    c === "talento humano" ||
    c === "recursos humanos"
  ) {
    return "AREA_RRHH";
  }

  if (
    c.includes("gerente") &&
    (
      c.includes("rrhh") ||
      c.includes("recursos humanos") ||
      c.includes("talento humano")
    )
  ) {
    return "GERENTE_RRHH";
  }

  if (
    c.includes("jefe corporativo") &&
    (
      c.includes("talento humano") ||
      c.includes("recursos humanos")
    )
  ) {
    return "JEFE_CORPORATIVO_RRHH";
  }

  if (
    (
      c.includes("sub jefe") ||
      c.includes("sub jefa")
    ) &&
    c.includes("talento humano")
  ) {
    return "SUBJEFE_RRHH";
  }

  if (
    (
      c.includes("jefe") ||
      c.includes("jefa")
    ) &&
    (
      c.includes("tthh") ||
      c.includes("talento humano") ||
      c.includes("recursos humanos")
    )
  ) {
    return "JEFE_RRHH";
  }

  if (
    c.includes("asistente") &&
    c.includes("talento humano")
  ) {
    return "ASISTENTE_RRHH";
  }

  if (
    c.includes("coordinador") &&
    c.includes("talento humano")
  ) {
    return "COORDINADOR_RRHH";
  }

  if (
    c.includes("analista") &&
    (
      c.includes("talento humano") ||
      c.includes("recursos humanos")
    )
  ) {
    return "ANALISTA_RRHH";
  }

  return c || "NO_IDENTIFICADO";
}


// ============================================================
// ¿ES CARGO ESPECÍFICO?
// ============================================================

function cargoEspecifico(cargo) {

  const clave =
    claveCargo(cargo);

  return (
    clave !== "AREA_RRHH" &&
    clave !== "NO_IDENTIFICADO"
  );
}


// ============================================================
// EMAIL ENMASCARADO
// ============================================================

function contieneEmailEnmascarado(texto) {

  return (
    /\*+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/i.test(texto) ||
    /[A-Za-z0-9]\*{2,}@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/i.test(texto)
  );
}


// ============================================================
// PROCESAR
// ============================================================

const salida = [];

for (
  let i = 0;
  i < respuestas.length;
  i++
) {

  const respuesta =
    respuestas[i]?.json || {};

  const candidato =
    candidatosMemoria[i]?.json || {};

  const persona =
    candidato.persona_contacto ||
    "NO ENCONTRADO";

  const empresa =
    candidato.empresa ||
    "NO IDENTIFICADO";

  const cargoDeclarado =
    candidato.cargo_declarado ||
    "NO IDENTIFICADO";

  const resultados =
    Array.isArray(respuesta.results)
      ? respuesta.results
      : [];


  const evidenciasValidas = [];
  const cargosDetectados = [];
  const emailsEnmascarados = [];
  const resultadosIrrelevantes = [];

  let fuentesFuertes = 0;
  let fuentesMedias = 0;

  let personaConfirmada = false;
  let empresaConfirmada = false;
  let rrhhConfirmado = false;


  // ==========================================================
  // RESULTADOS
  // ==========================================================

  for (const r of resultados) {

    const titulo =
      limpiar(r.title);

    const contenido =
      limpiar(r.content);

    const url =
      limpiar(r.url);

    const dominio =
      dominioDe(url);

    const texto =
      `${titulo} ${contenido}`;


    const confirmaPersona =
      mencionaPersona(
        texto,
        persona
      );

    const mencionaEmpresa =
      contiene(
        texto,
        "Corporacion Favorita"
      );

    const mencionaRRHH =
      (
        contiene(texto, "Talento Humano") ||
        contiene(texto, "Recursos Humanos") ||
        contiene(texto, "RRHH") ||
        contiene(texto, "TTHH") ||
        contiene(texto, "Human Resources")
      );


    // --------------------------------------------------------
    // SOLO EVIDENCIA DE PERSONA + EMPRESA
    // --------------------------------------------------------

    if (
      !confirmaPersona ||
      !mencionaEmpresa
    ) {

      resultadosIrrelevantes.push({
        titulo,
        url,
        motivo:
          "NO_CONFIRMA_PERSONA_Y_EMPRESA"
      });

      continue;
    }


    personaConfirmada = true;
    empresaConfirmada = true;

    if (mencionaRRHH) {
      rrhhConfirmado = true;
    }


    // --------------------------------------------------------
    // NIVEL DE FUENTE
    // --------------------------------------------------------

    let nivelFuente =
      "BAJA";

    if (
      esFuenteFuerte(url)
    ) {

      nivelFuente =
        "FUERTE";

      fuentesFuertes++;

    } else if (
      esFuenteMedia(url)
    ) {

      nivelFuente =
        "MEDIA";

      fuentesMedias++;
    }


    // --------------------------------------------------------
    // CARGO
    // --------------------------------------------------------

    const cargo =
      extraerCargo(texto);

    if (
      cargo !==
      "NO IDENTIFICADO"
    ) {

      cargosDetectados.push({

        cargo,

        clave_cargo:
          claveCargo(cargo),

        fuente:
          url,

        dominio,

        nivel_fuente:
          nivelFuente,

        evidencia:
          contenido
      });
    }


    // --------------------------------------------------------
    // EMAIL ENMASCARADO
    // --------------------------------------------------------

    if (
      contieneEmailEnmascarado(texto)
    ) {

      emailsEnmascarados.push({

        evidencia:
          texto,

        fuente:
          url,

        utilizable:
          false
      });
    }


    // --------------------------------------------------------
    // EVIDENCIA VÁLIDA
    // --------------------------------------------------------

    evidenciasValidas.push({

      titulo,

      url,

      dominio,

      nivel_fuente:
        nivelFuente,

      evidencia:
        contenido
    });
  }


  // ==========================================================
  // DEDUPLICAR VARIANTES EXACTAS
  // ==========================================================

  const vistosCargo =
    new Set();

  const cargosUnicos =
    cargosDetectados.filter(c => {

      const clave =
        `${c.clave_cargo}|${normalizar(c.cargo)}|${c.fuente}`;

      if (
        vistosCargo.has(clave)
      ) {
        return false;
      }

      vistosCargo.add(clave);

      return true;
    });


  // ==========================================================
  // CARGOS ESPECÍFICOS
  // ==========================================================

  const cargosEspecificos =
    cargosDetectados.filter(
      c => cargoEspecifico(c.cargo)
    );


  // ==========================================================
  // CARGO PREFERIDO
  //
  // 1. Fuente fuerte
  // 2. Fuente media
  // 3. Cargo declarado
  // ==========================================================

  let cargoVerificado =
    cargoDeclarado;

  let fuenteCargo =
    candidato.fuente_inicial || "";

  let nivelCargo =
    "NO_VERIFICADO";


  const cargoFuerte =
    cargosEspecificos.find(
      c =>
        c.nivel_fuente ===
        "FUERTE"
    );


  if (cargoFuerte) {

    cargoVerificado =
      cargoFuerte.cargo;

    fuenteCargo =
      cargoFuerte.fuente;

    nivelCargo =
      "VERIFICADO_FUENTE_FUERTE";

  } else {

    const cargoMedio =
      cargosEspecificos.find(
        c =>
          c.nivel_fuente ===
          "MEDIA"
      );


    if (cargoMedio) {

      cargoVerificado =
        cargoMedio.cargo;

      fuenteCargo =
        cargoMedio.fuente;

      nivelCargo =
        "CARGO_FUENTE_MEDIA";
    }
  }


  // ==========================================================
  // CONFLICTO REAL
  //
  // Comparamos familias semánticas.
  // ==========================================================

  const familiasCargo =
    [
      ...new Set(
        cargosEspecificos
          .map(c =>
            c.clave_cargo
          )
          .filter(Boolean)
      )
    ];


  const conflictoCargo =
    familiasCargo.length > 1;


  // ==========================================================
  // ESTADO VERIFICACIÓN
  // ==========================================================

  let estadoVerificacion =
    "NO_VERIFICADO";


  // Persona + empresa + RRHH con fuente fuerte.
  if (
    personaConfirmada &&
    empresaConfirmada &&
    rrhhConfirmado &&
    fuentesFuertes >= 1
  ) {

    if (
      conflictoCargo
    ) {

      estadoVerificacion =
        "CONFLICTO_DE_CARGO";

    } else if (
      nivelCargo ===
      "VERIFICADO_FUENTE_FUERTE"
    ) {

      estadoVerificacion =
        "VERIFICADO";

    } else {

      // Ejemplo Samantha:
      // LinkedIn confirma pertenencia a Talento Humano,
      // pero cargo exacto viene de ZoomInfo.
      estadoVerificacion =
        "PARCIALMENTE_VERIFICADO";
    }

  } else if (
    personaConfirmada &&
    empresaConfirmada &&
    rrhhConfirmado
  ) {

    estadoVerificacion =
      "PARCIALMENTE_VERIFICADO";
  }


  // ==========================================================
  // CONFIANZA
  // ==========================================================

  let confianza =
    "BAJA";

  if (
    estadoVerificacion ===
    "VERIFICADO"
  ) {

    confianza =
      "ALTA";

  } else if (
    estadoVerificacion ===
      "CONFLICTO_DE_CARGO" ||
    estadoVerificacion ===
      "PARCIALMENTE_VERIFICADO"
  ) {

    confianza =
      "MEDIA";
  }


  // ==========================================================
  // SALIDA
  // ==========================================================

  salida.push({

    json: {

      empresa,

      persona_contacto:
        persona,

      cargo_declarado:
        cargoDeclarado,

      estado_verificacion:
        estadoVerificacion,

      confianza_verificacion:
        confianza,

      cargo_verificado:
        cargoVerificado,

      fuente_cargo:
        fuenteCargo,

      nivel_verificacion_cargo:
        nivelCargo,

      conflicto_cargo:
        conflictoCargo,

      familias_cargo_detectadas:
        familiasCargo,

      cargos_encontrados:
        cargosUnicos,

      total_fuentes_validas:
        evidenciasValidas.length,

      fuentes_fuertes:
        fuentesFuertes,

      fuentes_medias:
        fuentesMedias,

      evidencias_validas:
        evidenciasValidas,

      emails_enmascarados_no_utilizables:
        emailsEnmascarados,

      estado_contacto:
        "SIN_CONTACTO_DIRECTO_VERIFICADO",

      resultados_irrelevantes:
        resultadosIrrelevantes,

      siguiente_accion:
        estadoVerificacion ===
          "VERIFICADO"
          ? "BUSCAR_CONTACTO_PUBLICO_VERIFICABLE"

          : estadoVerificacion ===
            "CONFLICTO_DE_CARGO"
            ? "MANTENER_PERSONA_Y_RESOLVER_CARGO"

          : estadoVerificacion ===
            "PARCIALMENTE_VERIFICADO"
            ? "AMPLIAR_EVIDENCIA_PERSONA"

          : "DESCARTAR_O_REINTENTAR_VERIFICACION"

    }
  });
}


return salida;
